export const OBJECT_GROUPS=['Trees & plants','Buildings','Furniture','Signs & street','Rocks & ruins','Ground details','Water & outdoors','Other'];
export const TERRAIN_GROUPS=['Grass & ground','Paths & paving','Water','Snow & ice','Caves & rock','Other'];
const text=p=>[p.name,p.category,Array.isArray(p.tags)?p.tags.join(' '):p.tags,p.source,p.packName,p.region].filter(Boolean).join(' ').toLowerCase();
export function objectGroup(p){const s=text(p),name=String(p.name||'').toLowerCase();if(/puddle|rug\b|carpet|floor|doormat|mat\b|ground detail/.test(s))return'Ground details';if(p.buildingTemplateId||p.category?.startsWith('Buildings'))return'Buildings';if(/tree|sapling|conifer|palm|plant|flower|shrub|mushroom|stump|log\b|topiar|cact/.test(name))return'Trees & plants';if(/rock|boulder|ruin|rubble|stone pillar/.test(name))return'Rocks & ruins';if(/sign|lamp|light post|street|bin\b|rubbish|fence|mailbox|postbox/.test(name))return'Signs & street';if(/boat|water|pond|pool|lifebuoy|buoy|bridge/.test(name))return'Water & outdoors';if(/interior|furnish|centre|center|mart|laborator|kitchen|seating|table|chair|bed|sofa|counter|shelf|bookcase|wardrobe|desk|cabinet|pc\b|machine/.test(s))return'Furniture';return'Other';}
export function terrainGroup(p){const s=text(p);if(/water|coast|coral|sea\b|ocean|river|lake/.test(s))return'Water';if(/snow|ice|frost/.test(s))return'Snow & ice';if(/cave|moon|volcano|lava|rocky/.test(s))return'Caves & rock';if(/path|pav|brick|cobbl|slab|crossing|trail|road|gravel/.test(s))return'Paths & paving';if(/grass|lawn|ground|sand|earth|soil/.test(s))return'Grass & ground';return'Other';}
export function matchesAsset(p,query){return String(query).toLowerCase().trim().split(/\s+/).every(word=>text(p).includes(word));}
export function loadAssetPreferences(){try{const p=JSON.parse(localStorage.getItem('pokebacon-asset-browser-v1')||'{}');return{favorites:Array.isArray(p.favorites)?p.favorites.filter(x=>typeof x==='string').slice(0,512):[],recent:Array.isArray(p.recent)?p.recent.filter(x=>typeof x==='string').slice(0,40):[]};}catch{return{favorites:[],recent:[]};}}
export function saveAssetPreferences(p){try{localStorage.setItem('pokebacon-asset-browser-v1',JSON.stringify(p));}catch{}}
export function rememberAsset(p,key){p.recent=[key,...p.recent.filter(id=>id!==key)].slice(0,40);saveAssetPreferences(p);}
export function toggleAssetFavorite(p,key){p.favorites=p.favorites.includes(key)?p.favorites.filter(id=>id!==key):[key,...p.favorites].slice(0,512);saveAssetPreferences(p);}
export function sortAssets(items,p,prefix){return [...items].sort((a,b)=>{const ka=prefix+a.id,kb=prefix+b.id,star=Number(p.favorites.includes(kb))-Number(p.favorites.includes(ka));if(star)return star;const ai=p.recent.indexOf(ka),bi=p.recent.indexOf(kb);if(ai!==bi)return(ai<0?999:ai)-(bi<0?999:bi);return String(a.name).localeCompare(String(b.name),undefined,{numeric:true});});}
